CREATE TABLE organisation_change_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organisation_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, before_json LONGTEXT NOT NULL, after_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organisation_id) REFERENCES organisations(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
